
#include "mml_cutscene_v2.h"
#include <string.h>
static MMLCutActor*actor(MMLCutscene*s,uint32_t id){for(size_t i=0;i<s->actor_count;i++)if(s->actors[i].id==id)return &s->actors[i];if(s->actor_count>=MML_CUT_MAX_ACTORS)return 0;MMLCutActor*a=&s->actors[s->actor_count++];memset(a,0,sizeof(*a));a->id=id;return a;}
void mml_cutscene_init(MMLCutscene*s,const MMLCutCue*c,size_t n,bool classic){if(!s)return;memset(s,0,sizeof(*s));s->code=c;s->count=n;s->classic=classic;s->gameplay_frozen=true;}
bool mml_cutscene_step(MMLCutscene*s){if(!s||s->halted||s->pc>=s->count||s->handoff_pending)return false;const MMLCutCue*q=&s->code[s->pc];if(s->classic&&q->evidence==MML_EVIDENCE_UNKNOWN)return false;switch(q->op){case MML_CUT_END:s->halted=true;break;case MML_CUT_ACTOR_XFORM:{MMLCutActor*a=actor(s,q->a);if(!a)return false;a->x=q->x;a->y=q->y;a->z=q->z;a->yaw12=(uint16_t)q->b;break;}case MML_CUT_ANIM:{MMLCutActor*a=actor(s,q->a);if(!a)return false;a->anim=(uint8_t)q->b;a->frame=(uint8_t)q->c;break;}case MML_CUT_EXPRESSION:{MMLCutActor*a=actor(s,q->a);if(!a)return false;a->expression=(uint8_t)q->b;a->eye=(uint8_t)(q->c&0xff);a->mouth=(uint8_t)((q->c>>8)&0xff);break;}case MML_CUT_MESSAGE:if(s->message_count>=16)return false;s->message_ids[s->message_count++]=q->a;break;case MML_CUT_AUDIO:if(s->audio_count>=MML_CUT_MAX_AUDIO)return false;s->audio_ids[s->audio_count++]=q->a;break;case MML_CUT_TRANSITION:memcpy(s->transition_payload,q->payload,0x18);s->transition_pending=true;break;case MML_CUT_HANDOFF:s->handoff_pending=true;s->handoff_token=q->a;break;case MML_CUT_CAMERA:case MML_CUT_FADE:break;default:return false;}s->pc++;return true;}
bool mml_cutscene_ack_handoff(MMLCutscene*s,uint32_t t){if(!s||!s->handoff_pending||s->handoff_token!=t)return false;s->handoff_pending=false;s->gameplay_frozen=false;return true;}
